using System;
using System.IO;
using System.Linq;
using System.Text;
using System.Security.Cryptography;
using IdleIntelligence.Core;
using IdleIntelligence.Runtime;
using NUnit.Framework;
namespace IdleIntelligence.Tests
{
 public sealed class GemSaveTests
 {
  static string Raw(StateData d,int version){var c=new UnitySaveCodec();string p=c.Encode(d),hash;using(var h=SHA256.Create())hash=BitConverter.ToString(h.ComputeHash(Encoding.UTF8.GetBytes(p))).Replace("-","").ToLowerInvariant();return c.EncodeEnvelope(new SaveEnvelope{format=AtomicSaveStore.Format,version=version,payload=p,sha256=hash});}
  [Test]public void V12OriginalAndInventorySurviveMigrationAndPermanentUpgradesSurviveReload()
  {string dir=Path.Combine(Path.GetTempPath(),"unity-gem-v12-"+Guid.NewGuid());Directory.CreateDirectory(dir);try{var s=Game.New(1000000);s.Retention.gems=10000;s.Prestige.resets=1;s=RetentionRules.CreateItem(s,"quantum-chip",1);var d=StateData.From(s);d.upgrades=null;d.capsules=null;string path=Path.Combine(dir,"save.json"),raw=Raw(d,12);File.WriteAllText(path,raw);var store=new AtomicSaveStore(path,new UnitySaveCodec());var load=store.Load(s.SavedAt);Assert.That(load.Writable,Is.True,load.Message);Assert.That(load.State.Capsules.draws,Is.Zero);Assert.That(load.State.Upgrades.processed,Is.Empty);Assert.That(load.State.Workshop.inventory.Single().id,Is.EqualTo(s.Workshop.inventory.Single().id));var bought=GemShop.Buy(load.State,"offline-12");bought=Capsules.Draw(bought,1,()=>.9999);store.Save(bought);Assert.That(File.ReadAllText(Directory.GetFiles(dir,"*.v12-original-*").Single()),Is.EqualTo(raw));var reload=new AtomicSaveStore(path,new UnitySaveCodec()).Load(s.SavedAt);Assert.That(reload.Writable,Is.True,reload.Message);Assert.That(reload.State.Upgrades.offlineSeconds,Is.EqualTo(43200));Assert.That(reload.State.Capsules.draws,Is.EqualTo(1));Assert.That(Capsules.Draw(reload.State,1),Is.SameAs(reload.State));Assert.That(GemShop.Buy(reload.State,"offline-12"),Is.SameAs(reload.State));}finally{Directory.Delete(dir,true);}}
  [Test]public void MissingCurrentMarkersOrInvalidReceiptLockOriginal()
  {string dir=Path.Combine(Path.GetTempPath(),"unity-gem-invalid-"+Guid.NewGuid());Directory.CreateDirectory(dir);try{string path=Path.Combine(dir,"save.json");for(int mode=0;mode<6;mode++){var s=Game.New(1000000);s.Prestige.resets=1;s.Retention.gems=10000;s=Capsules.Draw(s,1,()=>.5);var d=StateData.From(s);if(mode==0)d.upgrades=null;if(mode==1)d.capsules=null;if(mode==2)d.upgrades.purchasedLabs=3;if(mode==3)d.capsules.last.id=2;if(mode==4)d.upgrades.processed=new[]{"duplicate","duplicate"};if(mode==5)d.capsules.videos=7;string raw=Raw(d,13);File.WriteAllText(path,raw);Assert.That(new AtomicSaveStore(path,new UnitySaveCodec()).Load(s.SavedAt).Writable,Is.False,"invalid "+mode);Assert.That(File.ReadAllText(path),Is.EqualTo(raw));}}finally{Directory.Delete(dir,true);}}
  [Test]public void ChallengeReloadRetainsPaidMainUpgradesAndCapsuleReceipt()
  {string dir=Path.Combine(Path.GetTempPath(),"unity-gem-challenge-"+Guid.NewGuid());Directory.CreateDirectory(dir);try{var s=Game.New(1000000);s.Retention.gems=10000;s.Prestige.resets=1;s.Credits=ScientificNumber.From(1e20);s=Game.Buy(s,"sbc");foreach(string id in new[]{"offline-12","offline-16","offline-24","lab-boost"})s=GemShop.Buy(s,id);s=Capsules.Draw(s,1,()=>.9999);var run=ChallengeRules.Start(s,"no-taps",1,"gem-save-run");Assert.That(ChallengeRules.Active(run),Is.True);string path=Path.Combine(dir,"save.json");var store=new AtomicSaveStore(path,new UnitySaveCodec());Assert.That(store.Load(s.SavedAt).Writable,Is.True);store.Save(run);var load=new AtomicSaveStore(path,new UnitySaveCodec()).Load(s.SavedAt);Assert.That(load.Writable,Is.True,load.Message);var returned=ChallengeRules.Return(Game.Advance(load.State,s.SavedAt+100000),false);Assert.That(returned.Upgrades.offlineSeconds,Is.EqualTo(86400));Assert.That(returned.Upgrades.labBoostUntil,Is.EqualTo(s.Upgrades.labBoostUntil+100000));Assert.That(returned.Capsules.draws,Is.EqualTo(1));Assert.That(returned.Retention.gems,Is.EqualTo(s.Retention.gems));Assert.That(returned.Capsules.last.kind,Is.EqualTo("jackpot"));var bad=StateData.From(run);bad.challengeMain.capsules=null;string raw=Raw(bad,13);File.WriteAllText(path,raw);Assert.That(new AtomicSaveStore(path,new UnitySaveCodec()).Load(s.SavedAt).Writable,Is.False);Assert.That(File.ReadAllText(path),Is.EqualTo(raw));}finally{Directory.Delete(dir,true);}}
  [Test]public void SavedVideoRequestNeedsMatchingContextAndDoesNotRewardOnFailureOrReplay()
  {var s=Game.New(1000000);s.Prestige.resets=1;s=Capsules.BeginVideo(s,"saved-request");var codec=new UnitySaveCodec();s=codec.Decode(codec.Encode(StateData.From(s))).ToState();var unavailable=Capsules.CompleteRequestedVideo(s,"saved-request","unavailable");Assert.That(unavailable.Capsules.hasRequest,Is.False);Assert.That(unavailable.Capsules.draws,Is.Zero);Assert.That(unavailable.Capsules.videos,Is.Zero);Assert.That(Capsules.CompleteRequestedVideo(unavailable,"saved-request","success"),Is.SameAs(unavailable));var late=s.Copy();late.SavedAt=s.Capsules.request.expiresAt+1;Assert.That(Capsules.CompleteRequestedVideo(late,"saved-request","success").Capsules.draws,Is.Zero);var changed=s.Copy();changed.Prestige.resets++;Assert.That(Capsules.CompleteRequestedVideo(changed,"saved-request","success").Capsules.draws,Is.Zero);var success=Capsules.CompleteRequestedVideo(s,"saved-request","success");Assert.That(success.Capsules.draws,Is.EqualTo(1));Assert.That(success.Capsules.videos,Is.EqualTo(1));Assert.That(Capsules.CompleteRequestedVideo(success,"saved-request","success"),Is.SameAs(success));}
 }
}
